Literal.Value:
'{
  "params": [
    {
      "name": "title",
      "value": ""
    },
    {
      "name": "subtitle",
      "value": ""
    },
    {
      "name": "higherIsBetter",
      "value": true
    },
    {
      "name": "valueFormat",
      "value": "$.1f"
    },
    {
      "name": "valueDivisor",
      "value": 1000
    },
    {
      "name": "valueSuffix",
      "value": "K"
    },
    {
      "name": "percentFormat",
      "value": "+.1%"
    },
    {
      "name": "sortBy",
      "value": "current"
    },
    {
      "name": "sortDescending",
      "value": true
    },
    {
      "name": "colorGood",
      "expr": "pbiColor(''good'')"
    },
    {
      "name": "colorBad",
      "expr": "pbiColor(''bad'')"
    },
    {
      "name": "colorNeutral",
      "expr": "pbiColor(''neutral'')"
    },
    {
      "name": "colorComparisonFill",
      "value": "#E1DFDD"
    },
    {
      "name": "colorComparisonOutline",
      "value": "#A19F9D"
    },
    {
      "name": "colorTextPrimary",
      "value": "#252423"
    },
    {
      "name": "colorTextSecondary",
      "value": "#605E5C"
    },
    {
      "name": "colorLabelOnBar",
      "value": "#FFFFFF"
    },
    {
      "name": "colorLabelOnNeutral",
      "value": "#252423"
    },
    {
      "name": "comparisonOutlineWidth",
      "value": 1
    },
    {
      "name": "lollipopHeadTint",
      "value": 0.75
    },
    {
      "name": "lollipopHeadStrokeWidth",
      "value": 1.5
    },
    {
      "name": "titleFontSize",
      "value": 13
    },
    {
      "name": "subtitleFontSize",
      "value": 10
    },
    {
      "name": "categoryFontSize",
      "value": 10
    },
    {
      "name": "valueFontSize",
      "value": 9
    },
    {
      "name": "percentFontSize",
      "value": 9.5
    },
    {
      "name": "labelColumnShare",
      "value": 0.26
    },
    {
      "name": "lollipopShare",
      "value": 0.18
    },
    {
      "name": "comparisonBarSize",
      "value": 0.42
    },
    {
      "name": "currentBarSize",
      "value": 0.3
    },
    {
      "name": "comparisonBarOffset",
      "value": -0.1
    },
    {
      "name": "currentBarOffset",
      "value": 0.12
    },
    {
      "name": "lollipopHeadRadius",
      "value": 4
    },
    {
      "name": "lollipopStemWidth",
      "value": 2
    }
  ],
  "data": {
    "name": "dataset"
  },
  "transform": [
    {
      "calculate": "isValid(datum[''Category'']) ? datum[''Category''] + '''' : ''(Blank)''",
      "as": "category"
    },
    {
      "calculate": "isValid(datum[''Current'']) && isFinite(toNumber(datum[''Current''])) ? toNumber(datum[''Current'']) : null",
      "as": "current"
    },
    {
      "calculate": "isValid(datum[''Comparison'']) && isFinite(toNumber(datum[''Comparison''])) ? toNumber(datum[''Comparison'']) : null",
      "as": "comparison"
    },
    {
      "calculate": "isValid(datum.current) && isValid(datum.comparison) && datum.comparison != 0 ? (datum.current - datum.comparison) / abs(datum.comparison) : null",
      "as": "difference"
    },
    {
      "calculate": "!isValid(datum.difference) || datum.difference == 0 ? ''neutral'' : ((datum.difference > 0) === (higherIsBetter === true || higherIsBetter === ''true'') ? ''good'' : ''bad'')",
      "as": "status"
    },
    {
      "calculate": "datum.status == ''good'' ? colorGood : datum.status == ''bad'' ? colorBad : colorNeutral",
      "as": "statusColor"
    },
    {
      "calculate": "rgb(datum.statusColor)",
      "as": "statusRgb"
    },
    {
      "calculate": "''rgb('' + round(datum.statusRgb.r + (255 - datum.statusRgb.r) * lollipopHeadTint) + '','' + round(datum.statusRgb.g + (255 - datum.statusRgb.g) * lollipopHeadTint) + '','' + round(datum.statusRgb.b + (255 - datum.statusRgb.b) * lollipopHeadTint) + '')''",
      "as": "headFill"
    },
    {
      "window": [
        {
          "op": "row_number",
          "as": "categoryRank"
        }
      ],
      "sort": [
        {
          "field": "category",
          "order": "ascending"
        }
      ]
    },
    {
      "calculate": "sortBy == ''category'' ? datum.categoryRank : sortBy == ''comparison'' ? datum.comparison : sortBy == ''difference'' ? datum.difference : datum.current",
      "as": "sortRaw"
    },
    {
      "calculate": "isValid(datum.sortRaw) ? (sortDescending ? -datum.sortRaw : datum.sortRaw) : 1e300",
      "as": "sortValue"
    },
    {
      "window": [
        {
          "op": "row_number",
          "as": "rowIndex"
        }
      ],
      "sort": [
        {
          "field": "sortValue",
          "order": "ascending"
        },
        {
          "field": "categoryRank",
          "order": "ascending"
        }
      ]
    },
    {
      "joinaggregate": [
        {
          "op": "count",
          "as": "rowCount"
        },
        {
          "op": "max",
          "field": "current",
          "as": "maxCurrent"
        },
        {
          "op": "max",
          "field": "comparison",
          "as": "maxComparison"
        },
        {
          "op": "min",
          "field": "difference",
          "as": "minDifference"
        },
        {
          "op": "max",
          "field": "difference",
          "as": "maxDifference"
        }
      ]
    },
    {
      "calculate": "(length(title) > 0 ? titleFontSize * 1.35 : 0) + (length(subtitle) > 0 ? subtitleFontSize * 1.35 : 0) + (length(title) + length(subtitle) > 0 ? 6 : 0)",
      "as": "plotTop"
    },
    {
      "calculate": "width * labelColumnShare",
      "as": "labelRight"
    },
    {
      "calculate": "datum.labelRight + 8",
      "as": "barStart"
    },
    {
      "calculate": "percentFontSize * 5",
      "as": "percentSpace"
    },
    {
      "calculate": "width - datum.percentSpace - 4",
      "as": "lollipopRight"
    },
    {
      "calculate": "datum.lollipopRight - width * lollipopShare",
      "as": "lollipopLeft"
    },
    {
      "calculate": "max(datum.lollipopLeft - 10 - datum.barStart, 1)",
      "as": "barSpan"
    },
    {
      "calculate": "max(isValid(datum.maxCurrent) ? datum.maxCurrent : 0, isValid(datum.maxComparison) ? datum.maxComparison : 0) > 0 ? max(isValid(datum.maxCurrent) ? datum.maxCurrent : 0, isValid(datum.maxComparison) ? datum.maxComparison : 0) : 1",
      "as": "valueMax"
    },
    {
      "calculate": "datum.barStart + max(0, isValid(datum.current) ? datum.current : 0) / datum.valueMax * datum.barSpan",
      "as": "currentX"
    },
    {
      "calculate": "datum.barStart + max(0, isValid(datum.comparison) ? datum.comparison : 0) / datum.valueMax * datum.barSpan",
      "as": "comparisonX"
    },
    {
      "calculate": "max(0, height - datum.plotTop) / datum.rowCount",
      "as": "rowHeight"
    },
    {
      "calculate": "datum.plotTop + (datum.rowIndex - 0.5) * datum.rowHeight",
      "as": "rowCenter"
    },
    {
      "calculate": "datum.rowCenter + (comparisonBarOffset - comparisonBarSize / 2) * datum.rowHeight",
      "as": "comparisonTop"
    },
    {
      "calculate": "datum.comparisonTop + comparisonBarSize * datum.rowHeight",
      "as": "comparisonBottom"
    },
    {
      "calculate": "datum.rowCenter + (currentBarOffset - currentBarSize / 2) * datum.rowHeight",
      "as": "currentTop"
    },
    {
      "calculate": "datum.currentTop + currentBarSize * datum.rowHeight",
      "as": "currentBottom"
    },
    {
      "calculate": "(min(datum.comparisonTop, datum.currentTop) + max(datum.comparisonBottom, datum.currentBottom)) / 2",
      "as": "groupCenter"
    },
    {
      "calculate": "datum.currentTop > datum.comparisonTop ? (datum.comparisonTop + min(datum.currentTop, datum.comparisonBottom)) / 2 : (datum.comparisonTop + datum.comparisonBottom) / 2",
      "as": "comparisonLabelY"
    },
    {
      "calculate": "(datum.currentTop + datum.currentBottom) / 2",
      "as": "currentLabelY"
    },
    {
      "calculate": "isValid(datum.current) ? format(datum.current / valueDivisor, valueFormat) + valueSuffix : ''''",
      "as": "currentText"
    },
    {
      "calculate": "isValid(datum.comparison) ? format(datum.comparison / valueDivisor, valueFormat) + valueSuffix : ''''",
      "as": "comparisonText"
    },
    {
      "calculate": "datum.currentX - datum.barStart >= length(datum.currentText) * valueFontSize * 0.55 + 6",
      "as": "currentInside"
    },
    {
      "calculate": "datum.comparisonX - datum.barStart >= length(datum.comparisonText) * valueFontSize * 0.55 + 6",
      "as": "comparisonInside"
    },
    {
      "calculate": "(datum.currentTop > datum.comparisonTop ? min(datum.currentTop, datum.comparisonBottom) : datum.comparisonBottom) - datum.comparisonTop >= valueFontSize",
      "as": "comparisonLabelFits"
    },
    {
      "calculate": "datum.status == ''neutral'' ? colorLabelOnNeutral : colorLabelOnBar",
      "as": "currentLabelColor"
    },
    {
      "calculate": "min(0, isValid(datum.minDifference) ? datum.minDifference : 0)",
      "as": "differenceMin"
    },
    {
      "calculate": "max(0, isValid(datum.maxDifference) ? datum.maxDifference : 0)",
      "as": "differenceMax"
    },
    {
      "calculate": "datum.lollipopLeft + lollipopHeadRadius + 1",
      "as": "headLeft"
    },
    {
      "calculate": "max(datum.lollipopRight - lollipopHeadRadius - 1, datum.headLeft)",
      "as": "headRight"
    },
    {
      "calculate": "datum.headLeft + (0 - datum.differenceMin) / max(datum.differenceMax - datum.differenceMin, 1e-9) * (datum.headRight - datum.headLeft)",
      "as": "zeroX"
    },
    {
      "calculate": "isValid(datum.difference) ? datum.headLeft + (datum.difference - datum.differenceMin) / max(datum.differenceMax - datum.differenceMin, 1e-9) * (datum.headRight - datum.headLeft) : null",
      "as": "headX"
    },
    {
      "calculate": "isValid(datum.difference) ? format(datum.difference, percentFormat) : ''''",
      "as": "percentText"
    },
    {
      "calculate": "max(isValid(datum.headX) ? datum.headX + lollipopHeadRadius : 0, datum.zeroX) + 4",
      "as": "percentX"
    },
    {
      "calculate": "max(3, floor((datum.labelRight - 4) / (categoryFontSize * 0.52)))",
      "as": "labelChars"
    },
    {
      "calculate": "length(datum.category) <= datum.labelChars || datum.rowHeight < categoryFontSize * 2.5 ? -1 : (lastindexof(substring(datum.category, 0, datum.labelChars + 1), '' '') > 0 ? lastindexof(substring(datum.category, 0, datum.labelChars + 1), '' '') : indexof(datum.category, '' ''))",
      "as": "labelCut"
    },
    {
      "calculate": "datum.labelCut > 0 ? [substring(datum.category, 0, datum.labelCut), substring(datum.category, datum.labelCut + 1)] : [datum.category]",
      "as": "labelLines"
    }
  ],
  "encoding": {
    "tooltip": [
      {
        "field": "Category",
        "type": "nominal"
      },
      {
        "field": "currentText",
        "type": "nominal",
        "title": "Current"
      },
      {
        "field": "comparisonText",
        "type": "nominal",
        "title": "Comparison"
      },
      {
        "field": "percentText",
        "type": "nominal",
        "title": "Difference"
      }
    ]
  },
  "layer": [
    {
      "transform": [
        {
          "filter": "isValid(datum.comparison)"
        }
      ],
      "mark": {
        "type": "rect",
        "fill": {
          "expr": "colorComparisonFill"
        },
        "stroke": {
          "expr": "colorComparisonOutline"
        },
        "strokeWidth": {
          "expr": "comparisonOutlineWidth"
        }
      },
      "encoding": {
        "x": {
          "field": "barStart",
          "type": "quantitative",
          "scale": null
        },
        "x2": {
          "field": "comparisonX"
        },
        "y": {
          "field": "comparisonTop",
          "type": "quantitative",
          "scale": null
        },
        "y2": {
          "field": "comparisonBottom"
        }
      }
    },
    {
      "transform": [
        {
          "filter": "isValid(datum.current)"
        }
      ],
      "mark": {
        "type": "rect"
      },
      "encoding": {
        "x": {
          "field": "barStart",
          "type": "quantitative",
          "scale": null
        },
        "x2": {
          "field": "currentX"
        },
        "y": {
          "field": "currentTop",
          "type": "quantitative",
          "scale": null
        },
        "y2": {
          "field": "currentBottom"
        },
        "fill": {
          "field": "statusColor",
          "type": "nominal",
          "scale": null
        }
      }
    },
    {
      "transform": [
        {
          "filter": "isValid(datum.comparison) && datum.comparisonLabelFits && datum.comparisonInside"
        }
      ],
      "mark": {
        "type": "text",
        "align": "right",
        "baseline": "middle",
        "dx": -4,
        "fontSize": {
          "expr": "valueFontSize"
        },
        "fill": {
          "expr": "colorTextPrimary"
        }
      },
      "encoding": {
        "x": {
          "field": "comparisonX",
          "type": "quantitative",
          "scale": null
        },
        "y": {
          "field": "comparisonLabelY",
          "type": "quantitative",
          "scale": null
        },
        "text": {
          "field": "comparisonText",
          "type": "nominal"
        }
      }
    },
    {
      "transform": [
        {
          "filter": "isValid(datum.comparison) && datum.comparisonLabelFits && !datum.comparisonInside"
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "middle",
        "dx": 4,
        "fontSize": {
          "expr": "valueFontSize"
        },
        "fill": {
          "expr": "colorTextPrimary"
        }
      },
      "encoding": {
        "x": {
          "field": "comparisonX",
          "type": "quantitative",
          "scale": null
        },
        "y": {
          "field": "comparisonLabelY",
          "type": "quantitative",
          "scale": null
        },
        "text": {
          "field": "comparisonText",
          "type": "nominal"
        }
      }
    },
    {
      "transform": [
        {
          "filter": "isValid(datum.current) && datum.currentInside"
        }
      ],
      "mark": {
        "type": "text",
        "align": "right",
        "baseline": "middle",
        "dx": -4,
        "fontSize": {
          "expr": "valueFontSize"
        }
      },
      "encoding": {
        "x": {
          "field": "currentX",
          "type": "quantitative",
          "scale": null
        },
        "y": {
          "field": "currentLabelY",
          "type": "quantitative",
          "scale": null
        },
        "text": {
          "field": "currentText",
          "type": "nominal"
        },
        "fill": {
          "field": "currentLabelColor",
          "type": "nominal",
          "scale": null
        }
      }
    },
    {
      "transform": [
        {
          "filter": "isValid(datum.current) && !datum.currentInside"
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "middle",
        "dx": 4,
        "fontSize": {
          "expr": "valueFontSize"
        },
        "fill": {
          "expr": "colorTextPrimary"
        }
      },
      "encoding": {
        "x": {
          "field": "currentX",
          "type": "quantitative",
          "scale": null
        },
        "y": {
          "field": "currentLabelY",
          "type": "quantitative",
          "scale": null
        },
        "text": {
          "field": "currentText",
          "type": "nominal"
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "right",
        "baseline": "middle",
        "fontSize": {
          "expr": "categoryFontSize"
        },
        "lineHeight": {
          "expr": "categoryFontSize * 1.2"
        },
        "limit": {
          "expr": "max(width * labelColumnShare - 2, 10)"
        },
        "fill": {
          "expr": "colorTextPrimary"
        }
      },
      "encoding": {
        "x": {
          "field": "labelRight",
          "type": "quantitative",
          "scale": null
        },
        "y": {
          "field": "groupCenter",
          "type": "quantitative",
          "scale": null
        },
        "text": {
          "field": "labelLines",
          "type": "nominal"
        }
      }
    },
    {
      "transform": [
        {
          "filter": "isValid(datum.difference)"
        }
      ],
      "mark": {
        "type": "rule",
        "strokeWidth": {
          "expr": "lollipopStemWidth"
        },
        "strokeCap": "butt"
      },
      "encoding": {
        "x": {
          "field": "zeroX",
          "type": "quantitative",
          "scale": null
        },
        "x2": {
          "field": "headX"
        },
        "y": {
          "field": "groupCenter",
          "type": "quantitative",
          "scale": null
        },
        "stroke": {
          "field": "statusColor",
          "type": "nominal",
          "scale": null
        }
      }
    },
    {
      "transform": [
        {
          "filter": "isValid(datum.difference)"
        }
      ],
      "mark": {
        "type": "circle",
        "size": {
          "expr": "PI * lollipopHeadRadius * lollipopHeadRadius"
        },
        "strokeWidth": {
          "expr": "lollipopHeadStrokeWidth"
        },
        "opacity": 1
      },
      "encoding": {
        "x": {
          "field": "headX",
          "type": "quantitative",
          "scale": null
        },
        "y": {
          "field": "groupCenter",
          "type": "quantitative",
          "scale": null
        },
        "fill": {
          "field": "headFill",
          "type": "nominal",
          "scale": null
        },
        "stroke": {
          "field": "statusColor",
          "type": "nominal",
          "scale": null
        }
      }
    },
    {
      "transform": [
        {
          "filter": "isValid(datum.difference)"
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "middle",
        "fontSize": {
          "expr": "percentFontSize"
        },
        "limit": {
          "expr": "percentFontSize * 5"
        }
      },
      "encoding": {
        "x": {
          "field": "percentX",
          "type": "quantitative",
          "scale": null
        },
        "y": {
          "field": "groupCenter",
          "type": "quantitative",
          "scale": null
        },
        "text": {
          "field": "percentText",
          "type": "nominal"
        },
        "fill": {
          "field": "statusColor",
          "type": "nominal",
          "scale": null
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum.rowIndex === 1 && length(title) > 0"
        }
      ],
      "mark": {
        "type": "text",
        "text": {
          "expr": "title"
        },
        "x": 0,
        "y": 0,
        "align": "left",
        "baseline": "top",
        "fontSize": {
          "expr": "titleFontSize"
        },
        "fontWeight": "bold",
        "limit": {
          "expr": "width"
        },
        "fill": {
          "expr": "colorTextPrimary"
        }
      },
      "encoding": {
        "tooltip": null
      }
    },
    {
      "transform": [
        {
          "filter": "datum.rowIndex === 1 && length(subtitle) > 0"
        }
      ],
      "mark": {
        "type": "text",
        "text": {
          "expr": "subtitle"
        },
        "x": 0,
        "y": {
          "expr": "length(title) > 0 ? titleFontSize * 1.35 : 0"
        },
        "align": "left",
        "baseline": "top",
        "fontSize": {
          "expr": "subtitleFontSize"
        },
        "limit": {
          "expr": "width"
        },
        "fill": {
          "expr": "colorTextSecondary"
        }
      },
      "encoding": {
        "tooltip": null
      }
    }
  ]
}'
